func messageDeliveryLabel(msg repo.MessageData) string {
	if msg.DeliveryStatus >= 3 {
		if msg.IsGroup {
			return "Lida por participante"
		}
		return "Lida"
	}
	if msg.DeliveryStatus == 2 {
		if msg.IsGroup {
			return "Entregue a participante"
		}
		return "Entregue"
	}
	return "Enviada"
}

